import { EventEmitter } from 'node:events';

interface OrderEvents {
  'order.created': [orderId: string, customerEmail: string];
}

class TypedEmitter extends EventEmitter {
  emit<K extends keyof OrderEvents>(event: K, ...args: OrderEvents[K]): boolean {
    return super.emit(event, ...args);
  }
  on<K extends keyof OrderEvents>(event: K, listener: (...args: OrderEvents[K]) => void): this {
    return super.on(event, listener as (...args: unknown[]) => void);
  }
}

const bus = new TypedEmitter();
bus.on('order.created', (orderId, email) => {
  console.log(`file d'envoi email pour ${orderId} -> ${email}`);
});

bus.emit('order.created', 'ORD-9', 'client@example.com');

